using System;using System.IO;using System.Linq;using System.Text;using System.Diagnostics;using System.Collections.Generic;using System.Threading.Tasks;using KianaPet;
public static class ConnectionTests {
 static int count;static string root,exe;static DateTime now=DateTime.UtcNow;
 static void Check(bool value,string name){if(!value)throw new Exception(name);count++;}
 static HookEvent E(string kind,string turn="turn",string tool=null){return new HookEvent{SessionId="session",TurnId=turn,Event=kind,ToolId=tool,At=now};}
 static IEnumerable<T[]> Permute<T>(T[] values){if(values.Length==0){yield return new T[0];yield break;}for(int i=0;i<values.Length;i++)foreach(var tail in Permute(values.Where((v,j)=>i!=j).ToArray()))yield return new[]{values[i]}.Concat(tail).ToArray();}
 static void Ordering(){foreach(var order in Permute(new[]{"UserPromptSubmit","PermissionRequest","PostToolUse","Stop","Interrupt"})){var book=new HookBook();foreach(string kind in order){book.Apply(E(kind,tool:"call"));book.Apply(E(kind,tool:"call"));}Check(book.Data.Turns.Count==1&&book.State(book.Data.Turns[0],now)=="interrupted","terminal state survives all permutations and duplicates");}
  foreach(var order in Permute(new[]{"UserPromptSubmit","PermissionRequest","PostToolUse","Stop"})){var b=new HookBook();foreach(string kind in order)b.Apply(E(kind,tool:"call"));Check(b.State(b.Data.Turns[0],now)=="review","Stop is ended, never success");}
  var paired=new HookBook();paired.Apply(E("PostToolUse",tool:"a"));paired.Apply(E("PermissionRequest",tool:"a"));paired.Apply(E("UserPromptSubmit"));Check(paired.State(paired.Data.Turns[0],now)=="running","late permission event with known invocation cannot resurrect waiting");paired.Apply(E("PermissionRequest"));Check(paired.State(paired.Data.Turns[0],now)=="waiting","unpairable permission is conservative");paired.Apply(E("Stop"));Check(paired.State(paired.Data.Turns[0],now)=="review","terminal clears unresolved approval");
  var closed=new HookBook();closed.Apply(E("UserPromptSubmit"));closed.Apply(E("SessionEnd",null));Check(closed.State(closed.Data.Turns[0],now)=="unknown","missing terminal at session close is uncertain");Check(new HookBook(closed.Data).Snapshot(now,true).Notices[0].State=="unknown","uncertainty remains visible");
  var late=new HookBook();late.Apply(E("UserPromptSubmit","new"));var old=E("UserPromptSubmit","old");old.At=now.AddSeconds(-20);late.Apply(old);old=E("Stop","old");old.At=now.AddSeconds(2);late.Apply(old);Check(late.Snapshot(now.AddSeconds(2),true).Notices.Length==1&&late.Snapshot(now.AddSeconds(2),true).Notices[0].State=="running","late previous-turn Stop cannot replace current running turn");
  var stale=new HookBook();stale.Apply(E("UserPromptSubmit"));Check(stale.State(stale.Data.Turns[0],now.AddMinutes(6))=="unknown","silence is not inferred completion");var only=new HookBook();only.Apply(E("Interrupt"));Check(only.State(only.Data.Turns.Single(),now)=="interrupted"&&only.Snapshot(now,true).Notices.Length==0,"immediate interruption is correct even if initial hooks never ran");var snapshot=paired.Snapshot(now,true);Check(!snapshot.CanChat&&!snapshot.CanVoice&&!snapshot.CanOpenTasks&&snapshot.ConnectionSource=="hooks","Hooks exposes only its real capabilities");Check(!LinkHealth.Read(snapshot,true,now).Degraded,"missing Mini controls is expected in Hooks mode");Check(TaskNoticeHub.StateName("review")=="回合已结束","display never says success for Stop");
 }
 static string Log(string kind,string turn){return HookJournal.Json().Serialize(new{timestamp=(turn=="partial"?now.AddSeconds(1):now).ToString("o"),type="event_msg",payload=new{type=kind,turn_id=turn,secret="DO_NOT_PERSIST"}})+"\n";}
 static void RecoverTests(){string home=Path.Combine(root,"codex"),journal=Path.Combine(root,"journal");Directory.CreateDirectory(Path.Combine(home,"sessions"));string log=Path.Combine(home,"sessions","rollout-session.jsonl");File.WriteAllText(log,Log("task_started","turn")+Log("task_complete","turn"),new UTF8Encoding(false));var registration=E("SessionStart",null);registration.TranscriptPath=log;HookJournal.Atomic(Path.Combine(journal,"events","registration.json"),HookJournal.Json().Serialize(registration));
  var first=new HookConnection(journal,home).Read(now,true);Check(first.Notices.Single().State=="review","missing UserPromptSubmit and Stop recovered from registered transcript");Check(!File.ReadAllText(Path.Combine(journal,"checkpoint.json")).Contains("DO_NOT_PERSIST"),"recovery persists metadata only");Check(new HookConnection(journal,home).Read(now,true).Notices.Single().State=="review","checkpoint survives desktop pet restart");File.WriteAllText(Path.Combine(journal,"checkpoint.json"),"broken");Check(new HookConnection(journal,home).Read(now,true).Notices.Single().State=="review","journal and transcript recover damaged checkpoint");
  string partial=Log("task_complete","partial");File.WriteAllText(log,Log("task_started","partial")+partial.TrimEnd('\n'),new UTF8Encoding(false));Check(new HookConnection(journal,home).Read(now,true).Notices.Single().State=="running","incomplete trailing line is not accepted as terminal evidence");File.AppendAllText(log,"\n");Check(new HookConnection(journal,home).Read(now,true).Notices.Single().State=="review","complete final line recovers Stop");
  Check(HookJournal.ValidTranscript(Path.Combine(root,"rollout-session.jsonl"),"session",home)==null,"outside transcript roots rejected");Check(HookJournal.ValidTranscript(log,"different",home)==null,"wrong-session transcript rejected");Check(HookJournal.ValidTranscript(log,"session",home)==log,"registered local session permitted");
  string noPath=Path.Combine(root,"no-path");registration.TranscriptPath=null;HookJournal.Atomic(Path.Combine(noPath,"events","registration.json"),HookJournal.Json().Serialize(registration));Check(new HookConnection(noPath,home).Read(now,true).Notices.Single().State=="review","known-session filename fallback recovers without optional transcript_path");var checkpoint=HookJournal.Json().Deserialize<HookCheckpoint>(File.ReadAllText(Path.Combine(noPath,"checkpoint.json")));Check(checkpoint.Sessions.Single().TranscriptPath==log,"resolved path retained in metadata checkpoint");
 }
 static void Receiver(){string journal=Path.Combine(root,"receiver");var jobs=Enumerable.Range(0,16).Select(i=>Task.Run(()=>{var payload=HookJournal.Json().Serialize(new{hook_event_name=i%2==0?"Stop":"UserPromptSubmit",session_id="durable",turn_id="turn-"+(i/2),prompt="PRIVATE_PROMPT",tool_input=new{secret="PRIVATE_TOOL"},cwd="PRIVATE_CWD"});var start=new ProcessStartInfo{FileName=exe,Arguments="--hook-event --hook-root \""+journal+"\"",UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var process=Process.Start(start)){byte[] bytes=Encoding.UTF8.GetBytes(payload);process.StandardInput.BaseStream.Write(bytes,0,bytes.Length);process.StandardInput.Close();if(!process.WaitForExit(5000)||process.ExitCode!=0||process.StandardOutput.ReadToEnd().Length>0||process.StandardError.ReadToEnd().Length>0)throw new Exception("receiver process failed");}})).ToArray();Task.WaitAll(jobs);
  var files=Directory.GetFiles(Path.Combine(journal,"events"),"*.json");Check(files.Length==16,"all synchronous concurrent receipts flushed before process exit");Check(files.All(f=>{string text=File.ReadAllText(f);return !text.Contains("PRIVATE_");}),"receiver never persists prompt, arguments or cwd");var state=new HookConnection(journal).Read(DateTime.UtcNow,true);Check(state.Notices.Length==1&&state.Notices[0].State=="review","concurrent durable event replay produces ended task");
 }
 static Dictionary<string,object> Record(string name="Song",string artist="Artist"){return new Dictionary<string,object>{{"name",name},{"artists",new object[]{new Dictionary<string,object>{{"name",artist}}}},{"album",new Dictionary<string,object>{{"name","Album"}}},{"id","123"},{"duration",240000},{"playtime",(now-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc)).TotalMilliseconds}};}
 static void MusicTests(){var state=new MusicState{Connected=true,Playing=true,Title="Song",Artist="Artist",HasPosition=false,HasDuration=false,ConnectionSource="system",At=now};Check(ReadOnlyMusicCache.Supplement(state,Record(),now.AddMinutes(-1),now)&&state.Id=="123"&&state.Duration==240&&state.HasDuration&&!state.HasPosition,"ID and duration supplement never fabricates position");Check(!ReadOnlyMusicCache.Supplement(state,Record("Other"),now.AddMinutes(-1),now),"different title rejected");Check(!ReadOnlyMusicCache.Supplement(state,Record(artist:"Other"),now.AddMinutes(-1),now),"different lead artist rejected");Check(!ReadOnlyMusicCache.Supplement(state,Record(),now.AddMinutes(1),now),"record from previous process lifetime rejected");var bad=Record();bad["playtime"]=double.NaN;Check(!ReadOnlyMusicCache.Supplement(state,bad,now.AddMinutes(-1),now),"invalid cache timestamp rejected");
  var config=new Config{MusicEnabled=true,MusicEntryDelaySeconds=0,MusicNormalAction="quiet",MusicChorusAction="lively"};var ranges=new[]{new ChorusRange{Start=0,End=30}};Check(new MusicReactionPlanner().Choose(state,config,ranges,0,now,true)=="music-quiet","no position always uses normal listening action");state.HasPosition=true;Check(new MusicReactionPlanner().Choose(state,config,ranges,0,now,true)=="music-lively","original position-based chorus remains available");state.HasPosition=false;using(var library=new MusicLibrary()){library.Update(state,true);Check(library.Cue(state).Text.Contains("未提供进度"),"no position has explicit lyrics message");}Check(new Config().GPTConnectionMode=="cdp"&&new Config().MusicConnectionMode=="cdp","existing defaults preserved");config.GPTConnectionMode="bad";config.MusicConnectionMode="bad";config.Validate();Check(config.GPTConnectionMode=="cdp"&&config.MusicConnectionMode=="cdp","invalid provider choices safely default");Check(PreferenceReview.Local("GPTConnectionMode")&&PreferenceReview.Local("MusicConnectionMode"),"provider choices stay machine local");
 }
 static void SetupTests(){var other=new Dictionary<string,object>{{"matcher","*"},{"hooks",new object[]{new Dictionary<string,object>{{"type","command"},{"command","other.exe"}}}}};var config=new Dictionary<string,object>{{"description","keep"},{"hooks",new Dictionary<string,object>{{"Stop",new object[]{other}}}}};string command=HookSetup.Command(exe,root);config=HookSetup.Merge(config,command,exe,null);config=HookSetup.Merge(config,command,exe,null);var hooks=(Dictionary<string,object>)config["hooks"];Check((string)config["description"]=="keep"&&((object[])hooks["Stop"]).Length==2,"unrelated hooks and fields preserved; registration is idempotent");Check(HookJournal.Events.All(e=>((object[])hooks[e]).SelectMany(g=>(object[])MusicBridge.Get(g,"hooks")).Where(h=>MusicBridge.Str(h,"command")==command).Count()==1),"exactly seven owned handlers");Check(!HookJournal.Json().Serialize(config).Contains("\"async\""),"no fire-and-forget handlers remain");
  foreach(bool spaced in new[]{false,true})foreach(bool powershell in new[]{false,true}){string receipt=Path.Combine(root,spaced?"shell space":"shell"),script=Path.Combine(root,"shell-test."+(powershell?"ps1":"cmd"));string invocation=HookSetup.Command(exe,receipt);File.WriteAllText(script,(powershell?"":"@echo off\r\n")+invocation,new UTF8Encoding(false));var info=new ProcessStartInfo{FileName=powershell?"powershell.exe":"cmd.exe",Arguments=powershell?"-NoLogo -NoProfile -ExecutionPolicy Bypass -File \""+script+"\"":"/d /c \"\""+script+"\"\"",UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};var timer=Stopwatch.StartNew();using(var process=Process.Start(info)){byte[] bytes=Encoding.UTF8.GetBytes(HookJournal.Json().Serialize(new{session_id="shell",turn_id="turn-"+powershell,hook_event_name="Stop"}));process.StandardInput.BaseStream.Write(bytes,0,bytes.Length);process.StandardInput.Close();Check(process.WaitForExit(3000)&&process.ExitCode==0,"both shells wait for synchronous helper, including spaced paths");Check(process.StandardOutput.ReadToEnd().Length==0&&process.StandardError.ReadToEnd().Length==0,"native hook command emits no task-affecting output");}Check(Directory.GetFiles(Path.Combine(receipt,"events"),"*.json").Any(f=>File.ReadAllText(f).Contains("turn-"+powershell)),"receipt already durable when shell exits");File.AppendAllText(Path.Combine(root,"receiver-timings.txt"),powershell+" "+spaced+" "+timer.ElapsedMilliseconds+"ms\n");}
 }
 [STAThread]public static int Main(string[] args){root=args[0];exe=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"KianaHookReceiver.exe");Directory.CreateDirectory(root);try{Ordering();RecoverTests();Receiver();MusicTests();SetupTests();File.WriteAllText(Path.Combine(root,"result.txt"),"PASS "+count+" checks",Encoding.UTF8);return 0;}catch(Exception e){File.WriteAllText(Path.Combine(root,"error.txt"),e.ToString(),Encoding.UTF8);return 1;}}
}
